    thisown = property(lambda x: x.this.own(), lambda x, v: x.this.own(v), doc="The membership flag")

    def __init__(self, *args):
        r"""
        __init__(ExampleRestraint self, Model m, ParticleIndex p, double k) -> ExampleRestraint
        __init__(ExampleRestraint self) -> ExampleRestraint
        """
        _IMP_example.ExampleRestraint_swiginit(self, _IMP_example.new_ExampleRestraint(*args))

    def get_force_constant(self):
        r"""get_force_constant(ExampleRestraint self) -> double"""
        return _IMP_example.ExampleRestraint_get_force_constant(self)

    def get_index(self):
        r"""get_index(ExampleRestraint self) -> ParticleIndex"""
        return _IMP_example.ExampleRestraint_get_index(self)

    def do_add_score_and_derivatives(self, sa):
        r"""do_add_score_and_derivatives(ExampleRestraint self, ScoreAccumulator sa)"""
        return _IMP_example.ExampleRestraint_do_add_score_and_derivatives(self, sa)

    def do_get_inputs(self):
        r"""do_get_inputs(ExampleRestraint self) -> IMP::ModelObjectsTemp"""
        return _IMP_example.ExampleRestraint_do_get_inputs(self)

    def get_version_info(self):
        r"""get_version_info(ExampleRestraint self) -> VersionInfo"""
        return _IMP_example.ExampleRestraint_get_version_info(self)
    __swig_destroy__ = _IMP_example.delete_ExampleRestraint

    def __str__(self):
        r"""__str__(ExampleRestraint self) -> std::string"""
        return _IMP_example.ExampleRestraint___str__(self)

    def __repr__(self):
        r"""__repr__(ExampleRestraint self) -> std::string"""
        return _IMP_example.ExampleRestraint___repr__(self)

    @staticmethod
    def get_from(o):
       return _object_cast_to_ExampleRestraint(o)


    def _get_as_binary(self):
        r"""_get_as_binary(ExampleRestraint self) -> PyObject *"""
        return _IMP_example.ExampleRestraint__get_as_binary(self)

    def _set_from_binary(self, p):
        r"""_set_from_binary(ExampleRestraint self, PyObject * p)"""
        return _IMP_example.ExampleRestraint__set_from_binary(self, p)

    def __getstate__(self):
        p = self._get_as_binary()
        if len(self.__dict__) > 1:
            d = self.__dict__.copy()
            del d['this']
            p = (d, p)
        return p

    def __setstate__(self, p):
        if not hasattr(self, 'this'):
            self.__init__()
        if isinstance(p, tuple):
            d, p = p
            self.__dict__.update(d)
        return self._set_from_binary(p)


    def _get_jax(self):
        """Implementation of the restraint using JAX.
           For a Restraint, we must return a single JAX function which
           takes a single argument, the JAX Model, and returns its score.
           The JAX Model (here called `jm`) is a JAX object which contains
           the same information as the IMP Model, as a simple Python dict.
           For example, jm['xyz'] is an N x 3 array of XYZ coordinates."""
        import functools
        def jax_restraint(jm, k, pi):
    # Get the xyz coordinates for particle pi in the JAX Model
            xyz = jm['xyz'][pi]
    # Score the Z coordinate. Note that we do not need to calculate
    # its first derivatives; this is handled automatically by JAX.
            return 0.5 * k * xyz[2] * xyz[2]
    # We must return a function which takes only one argument, `jm`.
    # Here we use functools.partial to "bake in" the other parameters
    # k and pi, getting their values from the IMP Restraint object.
        f = functools.partial(jax_restraint, k=self.get_force_constant(),
                              pi=self.get_index())
    # Finally, we use the helper method _wrap_jax to return an object
    # that contains our JAX function and other restraint-specific
    # information, such as the weight
        return self._wrap_jax(f)


